							.nextTranslation(this.getTranslationKey() + ".name").color(TextFormatting.DARK_AQUA)
							.next("] ").color(TextFormatting.DARK_AQUA)
							.next("Locations cleared!").color(TextFormatting.RED).flush());
				}
			}
		}

		return stack;

